//! Valhalla protobuf message definitions.
//!
//! The types are generated by `prost` from the `.proto` files in `proto/`,
//! which are copied verbatim from Valhalla 3.9.1.
//! The top-level message passed between Valhalla services is [`Api`].

mod proto;

pub use proto::*;

// Re-export protobuf lib (for the traits).
pub use prost;

#[cfg(test)]
mod tests {
    use super::*;
    use prost::Message;
    use std::fs;
    use std::path::{Path, PathBuf};

    /// Mainline stage-boundary messages captured by `tools/oracle/capture.py`.
    ///
    /// The layout is `<region>/<case>/<format>/<boundary>.bin`,
    /// where boundary is `loki-thor` or `thor-odin`.
    const CAPTURES_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/captures");

    fn captured_messages() -> Vec<PathBuf> {
        fn visit(dir: &Path, out: &mut Vec<PathBuf>) {
            for entry in fs::read_dir(dir).expect("readable fixture directory") {
                let path = entry.expect("readable directory entry").path();
                if path.is_dir() {
                    visit(&path, out);
                } else if path.extension().is_some_and(|ext| ext == "bin") {
                    out.push(path);
                }
            }
        }

        let mut out = Vec::new();
        visit(Path::new(CAPTURES_DIR), &mut out);
        out.sort();
        out
    }

    fn decode_capture(relative: &str) -> Api {
        let bytes = fs::read(Path::new(CAPTURES_DIR).join(relative)).expect("fixture exists");
        Api::decode(bytes.as_slice()).expect("fixture decodes")
    }

    #[test]
    fn decode_api_message() {
        // A 3.5.1 status request, kept to show that older messages still decode.
        const MESSAGE: &[u8] = &[
            0xa, 0x43, 0x12, 0x5, 0x65, 0x6e, 0x2d, 0x55, 0x53, 0x40, 0xc, 0x50, 0x0, 0x58, 0x0,
            0x6a, 0xf, 0x8, 0x0, 0x12, 0xb, 0xa, 0x3, 0xb8, 0x3, 0x0, 0x1a, 0x4, 0x6e, 0x6f, 0x6e,
            0x65, 0xb8, 0x1, 0x0, 0xc5, 0x1, 0x0, 0x0, 0x80, 0x3f, 0xd0, 0x1, 0x0, 0xa8, 0x2, 0x0,
            0xb8, 0x2, 0x0, 0xc8, 0x2, 0x0, 0xe0, 0x2, 0x1, 0x80, 0x3, 0x0, 0x90, 0x3, 0x0, 0xb0,
            0x3, 0xff, 0xff, 0xff, 0xff, 0xf, 0x22, 0xa3, 0x1, 0x32, 0x5, 0x33, 0x2e, 0x35, 0x2e,
            0x31, 0x38, 0xee, 0xc5, 0xc4, 0xc5, 0x6, 0x42, 0x6, 0x73, 0x74, 0x61, 0x74, 0x75, 0x73,
            0x42, 0x8, 0x63, 0x65, 0x6e, 0x74, 0x72, 0x6f, 0x69, 0x64, 0x42, 0x9, 0x65, 0x78, 0x70,
            0x61, 0x6e, 0x73, 0x69, 0x6f, 0x6e, 0x42, 0x11, 0x74, 0x72, 0x61, 0x6e, 0x73, 0x69,
            0x74, 0x5f, 0x61, 0x76, 0x61, 0x69, 0x6c, 0x61, 0x62, 0x6c, 0x65, 0x42, 0x10, 0x74,
            0x72, 0x61, 0x63, 0x65, 0x5f, 0x61, 0x74, 0x74, 0x72, 0x69, 0x62, 0x75, 0x74, 0x65,
            0x73, 0x42, 0xb, 0x74, 0x72, 0x61, 0x63, 0x65, 0x5f, 0x72, 0x6f, 0x75, 0x74, 0x65,
            0x42, 0x9, 0x69, 0x73, 0x6f, 0x63, 0x68, 0x72, 0x6f, 0x6e, 0x65, 0x42, 0xf, 0x6f, 0x70,
            0x74, 0x69, 0x6d, 0x69, 0x7a, 0x65, 0x64, 0x5f, 0x72, 0x6f, 0x75, 0x74, 0x65, 0x42,
            0x12, 0x73, 0x6f, 0x75, 0x72, 0x63, 0x65, 0x73, 0x5f, 0x74, 0x6f, 0x5f, 0x74, 0x61,
            0x72, 0x67, 0x65, 0x74, 0x73, 0x42, 0x6, 0x68, 0x65, 0x69, 0x67, 0x68, 0x74, 0x42, 0x5,
            0x72, 0x6f, 0x75, 0x74, 0x65, 0x42, 0x6, 0x6c, 0x6f, 0x63, 0x61, 0x74, 0x65,
        ];
        let result = Api::decode(MESSAGE).expect("Failed to decode message");

        if !cfg!(miri) {
            insta::assert_debug_snapshot!(result);
        }
    }

    /// Every captured mainline message decodes, and re-encoding it loses nothing.
    ///
    /// `prost` does not promise byte-identical output
    /// (map entries in particular are written in hash order),
    /// so we compare decoded values.
    /// We also compare encoded lengths:
    /// `prost` silently drops fields it does not know,
    /// so a shorter re-encoding would mean our definitions are missing something
    /// that mainline sends at this boundary.
    #[test]
    fn captured_messages_round_trip() {
        let paths = captured_messages();
        // 32 cases across the two regions, less the three error cases and two locate cases
        // that never reach Thor, leaves 27; each has two formats and two boundaries.
        assert_eq!(paths.len(), 108, "unexpected number of captured messages");

        for path in paths {
            let bytes = fs::read(&path).expect("readable fixture");
            let decoded = Api::decode(bytes.as_slice())
                .unwrap_or_else(|e| panic!("{} failed to decode: {e}", path.display()));
            assert!(
                decoded.options.is_some(),
                "{} has no options",
                path.display()
            );

            let reencoded = decoded.encode_to_vec();
            assert_eq!(
                reencoded.len(),
                bytes.len(),
                "{} re-encoded to a different length",
                path.display()
            );
            let redecoded = Api::decode(reencoded.as_slice())
                .unwrap_or_else(|e| panic!("{} failed to re-decode: {e}", path.display()));
            assert_eq!(decoded, redecoded, "{} did not round-trip", path.display());
        }
    }

    /// Loki→Thor carries the parsed options and correlated locations, but no trip yet.
    #[test]
    fn loki_thor_capture_snapshot() {
        let api = decode_capture("andorra/bicycle_road/json/loki-thor.bin");
        assert!(api.trip.is_none());
        assert!(api.directions.is_none());

        if !cfg!(miri) {
            insta::assert_debug_snapshot!(api);
        }
    }

    /// Thor→Odin adds the trip.
    #[test]
    fn thor_odin_capture_snapshot() {
        let api = decode_capture("andorra/auto_same_street/json/thor-odin.bin");
        assert!(api.trip.is_some());
        assert!(api.directions.is_none());

        if !cfg!(miri) {
            insta::assert_debug_snapshot!(api);
        }
    }
}
